import * as React from 'react'
import{addPropertyControls,ControlType}from'framer'
import{CanchaStyle,ui}from'./CanchaUI.tsx'
// Replaces the retired Stories / Providers / Offers CMS collections (Framer Basic allows 2 collections).
// Items are generated by scripts/migrate-retiring-collections.mjs from the published CMS fields shown on the old pages.
const items:any[]=[]
const css=`.csp{padding:28px 0 60px}.csp-back{font-size:12px;color:#66765e!important;text-decoration:none;display:inline-block;margin-bottom:26px}
.csp-kicker{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#5f7457;margin:0 0 10px;font-weight:700}
.csp h1{font-size:clamp(38px,5vw,62px);margin:0 0 16px;overflow-wrap:anywhere}.csp-summary{font-size:16px;line-height:1.75;color:#4c6350;max-width:720px;margin:0 0 26px}
.csp-meta{display:flex;flex-wrap:wrap;gap:8px 18px;font-size:12px;color:#63745b;margin:0 0 24px}.csp-figure{margin:0 0 30px;max-width:900px}
.csp-figure img{width:100%;max-height:520px;object-fit:cover;border-radius:14px;display:block;background:#edf2e6}.csp-logo img{object-fit:contain;max-height:240px;padding:24px}.csp-figure figcaption{font-size:11px;color:#7a856f;margin-top:8px}
.csp-body{font-size:15px;line-height:1.85;max-width:720px;color:#25382c}.csp-body h2,.csp-body h3{margin:30px 0 10px}.csp-body a{color:#173f30}
.csp-section{max-width:720px;margin:28px 0 0}.csp-section h2{font-size:24px;margin:0 0 10px}.csp-note{font-size:12px;color:#6b7a62;max-width:720px;line-height:1.6}
.csp-btn{display:inline-block;margin-top:30px;background:#173f30;color:#fff!important;text-decoration:none;padding:14px 22px;border-radius:999px;font-weight:700;font-size:14px}
.csp-badge{display:inline-block;background:#d7ef86;color:#103f32;border-radius:999px;padding:5px 12px;font-size:11px;font-weight:700;margin-bottom:14px}
.csp-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:22px;margin-top:10px}.csp-card{border:1px solid #dfe6d9;border-radius:14px;background:#fff;overflow:hidden;display:flex;flex-direction:column;text-decoration:none;color:inherit}
.csp-card img{width:100%;height:180px;object-fit:cover;display:block;background:#edf2e6}.csp-card div{padding:18px 18px 20px;display:flex;flex-direction:column;gap:8px;flex:1}.csp-card h3{font-size:20px;margin:0}
.csp-card p{font-size:13px;line-height:1.6;margin:0;color:#4c6350}.csp-card span{margin-top:auto;font-weight:700;font-size:13px;color:#173f30}.csp-empty{border:1px dashed #cddcbe;border-radius:14px;padding:28px;max-width:720px}
@media(max-width:650px){.csp{padding:20px 0 40px}.csp h1{font-size:38px}.csp-summary{font-size:14px}.csp-body{font-size:14px}}`
const back:any={story:['/stories','Stories'],provider:['/providers','Providers'],offer:['/offers','Offers']}
const empty:any={story:['Our first stories are in review.','We’re preparing practical guides. Athlete and coach features will be based on real interviews.'],provider:['Providers are in review.','Coaches and services appear here after their details are checked.'],offer:['No offers right now.','Offers appear here only with the merchant’s terms and a clear disclosure.']}
function Detail({i}:any){const[href,label]=back[i.kind]
 return <article>{<a className="csp-back" href={href}>← Back to {label}</a>}
  {i.kicker&&<p className="csp-kicker">{i.kicker}</p>}<h1>{i.title}</h1>
  {i.credentialsReviewed&&<span className="csp-badge">Credentials reviewed</span>}
  {i.meta?.length>0&&<p className="csp-meta">{i.meta.map((m:string)=><span key={m}>{m}</span>)}</p>}
  {i.summary&&<p className="csp-summary">{i.summary}</p>}
  {i.image&&<figure className={"csp-figure"+(i.kind==='provider'?' csp-logo':'')}><img src={i.image} alt={i.imageAlt||''}/>{i.credit&&<figcaption>{i.creditLink?<a href={i.creditLink} rel="noopener" target="_blank">{i.credit}</a>:i.credit}</figcaption>}</figure>}
  {i.note&&<p className="csp-note">{i.note}</p>}
  {i.body&&<div className="csp-body" dangerouslySetInnerHTML={{__html:i.body}}/>}
  {(i.sections||[]).map((s:any)=><section className="csp-section" key={s.heading}><h2>{s.heading}</h2><div className="csp-body" dangerouslySetInnerHTML={{__html:s.html}}/></section>)}
  {i.priceNote&&<p className="csp-note" style={{marginTop:22}}>{i.priceNote}</p>}
  {i.link&&<a className="csp-btn" href={i.link} rel="noopener" target="_blank">{i.linkLabel||'Visit official page →'}</a>}
 </article>}
/** @framerSupportedLayoutWidth any @framerSupportedLayoutHeight auto */
export default function CanchaStaticPage({mode='detail',path='',kind='story'}:any){
 const list=mode==='list'?items.filter(i=>i.kind===kind):mode==='all'?items:items.filter(i=>i.path===path)
 return <main className="cancha-v2 csp"><CanchaStyle css={ui+css}/><div className="cv-wrap">
  {mode==='list'?(list.length?<div className="csp-list">{list.map(i=><a className="csp-card" key={i.path} href={i.path}>{i.image&&<img src={i.image} alt={i.imageAlt||''}/>}<div>{i.kicker&&<p className="csp-kicker" style={{margin:0}}>{i.kicker}</p>}<h3>{i.title}</h3>{i.summary&&<p>{i.summary}</p>}<span>{i.kind==='story'?'Read Story →':'View details →'}</span></div></a>)}</div>
   :<div className="csp-empty"><h2 style={{fontSize:24,margin:'0 0 8px'}}>{empty[kind][0]}</h2><p className="csp-note">{empty[kind][1]}</p></div>)
  :list.length?list.map(i=><Detail key={i.path} i={i}/>):<p className="csp-note">This page is being updated.</p>}
 </div></main>}
addPropertyControls(CanchaStaticPage,{mode:{type:ControlType.Enum,options:['detail','list','all'],defaultValue:'detail'},path:{type:ControlType.String,defaultValue:''},kind:{type:ControlType.Enum,options:['story','provider','offer'],defaultValue:'story'}})
